    <?php if ($preview !== []): ?><section class="panel"><h2>9. Revisar conflitos</h2><?php if (!empty($conflicts)): ?><p class="error">Conflitos encontrados: <?= count($conflicts) ?>. Ajuste periodo, horarios ou locais.</p><?php else: ?><p class="success">Previa sem conflitos. <?= count($preview) ?> partidas.</p><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Grupo</th><th>Rodada</th><th>Confronto</th><th>Data</th><th>Horario</th><th>Local</th></tr></thead><tbody><?php foreach ($preview as $item): ?><tr><td><?= App\Core\View::e($item['group_id']) ?></td><td><?= (int) $item['round_number'] ?></td><td><?= (int) $item['home_team_id'] ?> x <?= (int) $item['away_team_id'] ?></td><td><?= App\Core\View::e($item['match_date']) ?></td><td><?= App\Core\View::e($item['match_time']) ?></td><td><?= App\Core\View::e($item['venue_id'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (empty($conflicts)): ?><form method="post" action="<?= App\Core\View::e(App\Core\Config::url('/admin/tabela/assistente/confirmar')) ?>"><input type="hidden" name="_csrf" value="<?= App\Core\View::e(App\Core\Security::csrfToken()) ?>"><?php foreach ($data as $key => $value): ?><?php if (is_array($value)): ?><?php foreach ($value as $entry): ?><input type="hidden" name="<?= App\Core\View::e($key) ?>[]" value="<?= App\Core\View::e($entry) ?>"><?php endforeach; ?><?php else: ?><input type="hidden" name="<?= App\Core\View::e($key) ?>" value="<?= App\Core\View::e($value) ?>"><?php endif; ?><?php endforeach; ?><button type="submit">10. Confirmar tabela</button></form><?php endif; ?></section><?php endif; ?>
